namespace ghidra.app.plugin.core.sourcefilestable;

using docking.widgets.table;
using docking.widgets.table;
using docking.widgets.table.threaded;
using ghidra.docking.settings;
using ghidra.framework.plugintool;
using ghidra.program.database.sourcemap;
using ghidra.program.model.listing;
using ghidra.program.model.sourcemap;
using ghidra.program.model.sourcemap;
using ghidra.util.datastruct;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * A table model for source path transform information
 */
public class TransformerTableModel : ThreadedTableModelStub<SourcePathTransformRecord> {

	private SourceFilesTablePlugin plugin;
	private Program program;
	private SourcePathTransformer pathTransformer;

	/**
	 * Constructor
	 * @param plugin plugin
	 */
	public TransformerTableModel(SourceFilesTablePlugin plugin) : base("Transformer Table Model", plugin.getTool())
    {
		this.plugin = plugin;
		program = plugin.getCurrentProgram();
		if (program != null) {
			pathTransformer = UserDataPathTransformer.getPathTransformer(program);
		}
	}

	/**
	 * Returns the program used to populate the table 
	 * @return program
	 */
	protected Program getProgram() {
		return program;
	}

	/* @Override */
	protected void doLoad(Accumulator<SourcePathTransformRecord> accumulator, TaskMonitor monitor)
    {
		if (pathTransformer == null) {
			return;
		}
		foreach (SourcePathTransformRecord transformRecord in pathTransformer.getTransformRecords()) {
			accumulator.add(transformRecord);
		}
		return;
	}

	/* @Override */
	protected TableColumnDescriptor<SourcePathTransformRecord> createTableColumnDescriptor() {
		TableColumnDescriptor<SourcePathTransformRecord> descriptor = new();
		descriptor.addVisibleColumn(new SourceColumn());
		descriptor.addVisibleColumn(new TargetColumn());
		descriptor.addVisibleColumn(new IsDirectoryTransformColumn());
		return descriptor;
	}

	/**
	 * Reloads the table using the path transformer for {@code newProgram}.
	 * @param newProgram program
	 */
	protected void reloadProgram(Program newProgram) {
		program = newProgram;
		pathTransformer =
			program == null ? null
					: UserDataPathTransformer.getPathTransformer(plugin.getCurrentProgram());
		reload();
	}

	private class SourceColumn : AbstractDynamicTableColumn<SourcePathTransformRecord, string, object> {

		/* @Override */
		public string getColumnName() {
			return "Source";
		}

		/* @Override */
		public string getValue(SourcePathTransformRecord rowObject, Settings settings, object data,
				ServiceProvider services)
    {
			if (rowObject.isDirectoryTransform()) {
				return rowObject.source();
			}
			return rowObject.sourceFile().toString();
		}
	}

	private class TargetColumn : AbstractDynamicTableColumn<SourcePathTransformRecord, string, object> {

		/* @Override */
		public string getColumnName() {
			return "Target";
		}

		/* @Override */
		public string getValue(SourcePathTransformRecord rowObject, Settings settings, object data,
				ServiceProvider services)
    {
			return rowObject.target();
		}
	}

	private class IsDirectoryTransformColumn : AbstractDynamicTableColumn<SourcePathTransformRecord, Boolean, object> {

		/* @Override */
		public string getColumnName() {
			return "Directory Transform";
		}

		/* @Override */
		public Boolean getValue(SourcePathTransformRecord rowObject, Settings settings, object data,
				ServiceProvider services)
    {
			return rowObject.isDirectoryTransform();
		}
	}

}
